enabled:callback(function() if not enabled:get() then clear() end end)
local function glyph(ch, frame, cx, cy, size, tint, edge)
    local a = tint.a
    if a < 1 then return end
    local texture = textures[ch][frame]
    local side = 124 * size / 96
    local x, y = cx - side / 2, cy - side / 2
    render.image(texture, x + 2, y + 3, side, side, color(0, 0, 0, floor(a * 0.35)))
    if edge > 0 then
        local black = color(0, 0, 0, a)
        for _, p in ipairs(ring) do
            render.image(texture, x + p[1] * edge, y + p[2] * edge, side, side, black)
        end
    end
    render.image(texture, x, y, side, side, tint)
end
local function draw(hit, life, k, anim_speed, mode, edge, sw, sh)
    local x, y
    if hit.screen then
        x = sw * 0.5 + (hit.preview_x or 100) * k
        y = sh * (hit.screen == "test" and 0.38 or 0.62)
    elseif hit.pos then
        local p = vector(hit.pos.x, hit.pos.y, hit.pos.z + offset:get())
        x, y = render.world_to_screen(p)
    end
    if not finite(x) or not finite(y) then return end
    local fraction = clamp(hit.age / life, 0, 1)
    local phase = 1.5 * (1 - (1 - fraction)^anim_speed)
    local pop = 1
    if mode ~= 2 then
        if phase < 0.09 then pop = lerp(0.70, 1.15, ease(phase / 0.09))
        elseif phase < 0.19 then pop = lerp(1.15, 1, smooth((phase - 0.09) / 0.10)) end
    end
    local split = mode == 0 or mode == 3
    local split_at = mode == 3 and 0.20 or 0.34
    local decay = smooth((fraction - 0.68) / 0.32)
    local c = hit.head and head_color:get()
        or (use_armor:get() and hit.armor and armor_color:get() or body_color:get())
    local tint = color(c.r, c.g, c.b, math.ceil((c.a or 255) * (1 - decay)))
    local base = 48 * k * (hit.head and 1.2 or 1)
    local size = base * pop * (1 - (split and 0.22 or 0.08) * decay)
    local unit = size / 96
    local float = mode == 2 and -60 * ease(phase / 1.5) or -28 * ease(phase / 0.34)
    local flight = split and max(0, (phase - split_at) / (1.5 - split_at)) * 0.60 or 0
    x, y = x + hit.ox * k, y + (hit.oy + float) * k
    for _, d in ipairs(hit.digits) do
        local dx = (d.x + d.w / 2 - hit.width / 2) * unit + d.vx * flight * k
        local dy = (d.vy * flight + 0.5 * 900 * flight * flight) * k
        local px, py = x + dx, y + dy - metrics[d.ch].h * unit / 2
        if px > -size * 2 and px < sw + size and py > -size * 2 and py < sh + size then
            local frame = min(9, floor(flight * (100 + d.w % 30) / 10 + 0.5))
            if d.vx < 0 then frame = -frame end
            glyph(d.ch, frame, px, py, size, tint, edge * k)
        end
    end
end
on("paint", function()
    if not enabled:get() then clear(); return end
    local now = globals.realtime()
    if last_time and now < last_time then clear() end
    last_time = now
    if engine.in_game() then scan(now) else snapshots = {}; last_scan = -1 end
    local sw, sh = render.screen_size()
    if not finite(sw) or not finite(sh) then return end
    local life, k = duration:get(), scale:get() / 100
    local mode = style:get()
    if type(mode) == "string" then
        mode = ({["经典堡垒之夜"] = 0, ["弹跳"] = 1, ["漂浮"] = 2, ["分裂"] = 3})[mode] or 0
    end
    for i = #hits, 1, -1 do
        local hit = hits[i]
        local dt = max(0, now - hit.updated)
        hit.age, hit.updated = hit.age + dt, now
        if hit.age >= life or (hit.category and not allowed(hit.category))
            or (hit.screen ~= "test" and not engine.in_game()) then
            table.remove(hits, i)
        else draw(hit, life, k, speed:get(), mode, outline:get(), sw, sh) end
    end
end)
on("level_init", clear)
on("level_shutdown", clear)
on("unload", function()
    clear()
    for _, id in ipairs(callbacks) do events.off(id) end
    callbacks, metrics, ring, textures = {}, {}, {}, {}
end)
